INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2023', '{"numero":1,"ano":2023,"titulo":"I Feira da Sostibilidade","datas":"Abril de 2023","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"A edición pioneira. Impulsada polo colectivo Eco-Étika, uniu comunidade educativa, asociacións e comercio local arredor da sostibilidade.","cifras":[],"fitos":["Impulsada por Eco-Étika","Premio Galicons-net"],"seccions":[{"id":"s1or8k","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A primeira Feira da Sostibilidade naceu da iniciativa do colectivo Eco-Étika, formado por alumnado do IES Luís Seoane. Converteu o centro nun espazo pioneiro en Galicia que uniu comunidades educativas, asociacións e comercio local arredor da sostibilidade e o consumo responsable.</p>"},{"id":"s2mgj1","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsa","entidades":["cidel-galicia"]}]},{"id":"s3zunp","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane"]},{"id":"s4f3ej","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria I Edición"}]},{"id":"s5xwda","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2023","numero":6}]}', 977) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2024', '{"numero":2,"ano":2024,"titulo":"II Feira da Sostibilidade","datas":"Abril de 2024","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"Consolidación da rede. Incorpóranse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e hai stands do alumnado de varios centros.","cifras":[],"fitos":["Incorporación da Universidade de Vigo","Primeiros stands de varios centros","Debate público sobre consumismo e desinformación"],"seccions":[{"id":"s6ccd6","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A segunda edición consolidou a rede. Incorporáronse a Universidade de Vigo, o IES de Poio e o IES Rafael Dieste, e por primeira vez houbo stands do alumnado de varios centros e un debate público sobre consumismo e desinformación.</p>"},{"id":"s7za9e","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}]},{"id":"s8kx1i","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane","IES de Poio","IES Rafael Dieste"]},{"id":"s9x1en","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria II Edición"}]},{"id":"sahvoo","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2024","numero":6}]}', 976) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2025', '{"numero":3,"ano":2025,"titulo":"III Feira da Sostibilidade","datas":"Abril de 2025","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"Expansión a 9 centros educativos de Galicia e 22 entidades colaboradoras. Comeza a liña de ciencia cidadá co Post-Growth Innovation Lab.","cifras":[{"valor":"9","etiqueta":"centros educativos de Galicia"},{"valor":"22","etiqueta":"entidades colaboradoras"}],"fitos":["Inicio da liña de ciencia cidadá","Grupo de traballo intercentros aprobado polo CFR"],"seccions":[{"id":"sbov4s","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A terceira edición converteu a Feira nunha rede galega de innovación educativa. Participaron 9 centros educativos de Galicia e 22 entidades colaboradoras, e o CFR de Pontevedra aprobou o primeiro grupo de traballo intercentros.</p>\n<p>Nesta edición comezou a liña de ciencia cidadá co Post-Growth Innovation Lab da Universidade de Vigo, que converte o alumnado en investigador dos retos do seu territorio.</p>"},{"id":"scw9ev","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]}]},{"id":"sdtgvx","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane e 8 centros educativos de Galicia"]},{"id":"seqg3q","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria III Edición"}]},{"id":"sflzp9","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2025","numero":6}]}', 975) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2026', '{"numero":4,"ano":2026,"titulo":"IV Feira da Sostibilidade","datas":"Abril de 2026","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"pasada","resumo":"A máis grande ata o momento. 30 entidades e 13 centros educativos de Galicia, España e Europa, co I Foro de Desenvolvemento Local integrado na Feira.","portada":"f-stand-artesania","portadaAlt":"Alumnado nun stand de artesanía na IV Feira da Sostibilidade","cifras":[{"valor":"1.127","etiqueta":"participantes directos estimados"},{"valor":"30","etiqueta":"entidades colaboradoras"},{"valor":"13","etiqueta":"centros (9 Galicia · 2 España · 2 Europa)"},{"valor":"120+","etiqueta":"alumnos e alumnas presentando nos stands"},{"valor":"528","etiqueta":"alumnado activo en obradoiros e dinámicas"},{"valor":"6.870+","etiqueta":"impacto indirecto estimado"}],"fitos":["I Foro de Desenvolvemento Local","Estudo de ciencia cidadá sobre o consumo de alimentos","30 entidades"],"seccions":[{"id":"sgpejk","tipo":"texto","oculta":false,"fondo":"branco","etiqueta":"A edición","corpo":"<p>A cuarta edición consolidou a Feira como referente galego de educación transformadora. Participaron 30 entidades e 13 centros educativos de Galicia, doutras comunidades autónomas e de Europa.</p>\n<p>No marco da Feira celebrouse o I Foro de Desenvolvemento Local, onde o alumnado do IES Luís Seoane presentou o estudo de ciencia cidadá sobre o patrón de consumo de alimentos en Pontevedra, desenvolvido co Post-Growth Innovation Lab da Universidade de Vigo: 587 enquisas recollidas en 6 zonas do municipio e propostas de axenda local para reducir a pegada de carbono.</p>"},{"id":"shhcd2","tipo":"galeria","oculta":false,"fondo":"claro","etiqueta":"Galería","titulo":"Imaxes da edición.","imaxes":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"},{"imaxe":"f-exposicion-gravados","alt":"Panel cunha exposición de gravados en branco e negro"},{"imaxe":"f-stand-sociocultural","alt":"Stand de La Sociocultural con libros e carteis"},{"imaxe":"f-xogo-mesa","alt":"Xogo de mesa educativo creado polo alumnado"},{"imaxe":"f-alumnado-presenta-investigacion","alt":"Alumnado presentando os resultados da investigación cidadá"}]},{"id":"sijqt2","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara"]}]},{"id":"sjlpz7","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane","IES de Poio","IES Rafael Dieste","IES Val da Asma","IES Chapela","IES Antón Alonso Ríos","IES Rego de Trabe","CEP Marcos da Portela","EEI Fina Casalderey","CIPF A Xunqueira","2 centros doutras comunidades autónomas","2 centros europeos (Erasmus+)"]},{"id":"skd5pz","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Documentos","items":[{"titulo":"Memoria IV Edición (en breve)"}]},{"id":"slofpx","tipo":"documentos","oculta":false,"fondo":"branco","etiqueta":"Na prensa","items":[{"titulo":"Diario de Pontevedra"},{"titulo":"Pontevedra Viva"}]},{"id":"smcm70","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2026","numero":6}]}', 974) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('edicions', '2027', '{"numero":5,"ano":2027,"titulo":"V Feira da Sostibilidade · SENDA 2030","lema":"Eco-Étika en acción","datas":"28, 29 e 30 de abril de 2027","lugar":"IES Luís Seoane · Monte Porreiro, Pontevedra","estado":"proxima","resumo":"Tres xornadas abertas de stands, obradoiros, charlas-foro, demostracións, xogos e escape rooms. Nesta edición conflúen os 10 microproxectos Eco-Étika, o II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.","portada":"f-multitude-corredor","portadaAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira da Sostibilidade","cifras":[{"valor":"3","etiqueta":"xornadas"},{"valor":"~1.000","etiqueta":"participacións previstas"},{"valor":"13+","etiqueta":"centros educativos con papel activo"},{"valor":"10","etiqueta":"microproxectos Eco-Étika do alumnado"}],"fitos":["II Foro de Desenvolvemento Local","I Conferencia COOPEDUGAL","Microproxectos Eco-Étika. Pensa. Actúa.","Voces do Sur Global"],"proxecto":"senda-2030","seccions":[{"id":"snq5na","tipo":"texto_imaxe","oculta":false,"fondo":"branco","ancla":"senda-2030","etiqueta":"O camiño ata a Feira","titulo":"Unha Feira que se constrúe durante todo o curso.","corpo":"<p>A quinta edición da Feira da Sostibilidade dá continuidade ás catro anteriores como espazo aberto de participación, intercambio e sensibilización arredor dos retos ecosociais e das alternativas para abordalos.</p>\n<p>Celébrase nun centro cunha comunidade educativa de arredor de 1.460 persoas e reúne centros educativos, a Universidade de Vigo, entidades sociais, ONGD, administracións, empresas e outras iniciativas do territorio. O protagonismo é do alumnado e do profesorado, que presentan, dinamizan e comparten os coñecementos, experiencias e propostas construídos durante o curso.</p>\n<p>Esta edición forma parte de <strong>SENDA 2030. Xeración Eco-Étika</strong>, un proxecto de Educación para o Desenvolvemento e a Cidadanía Global que conecta ciencia cidadá, práctica docente e participación xuvenil, con experiencias e voces de República Dominicana e outros territorios de América Latina.</p><p>SENDA 2030 é unha proposta de Educación para o Desenvolvemento e a Cidadanía Global promovida en agrupación por <strong>CIDEL Galicia</strong> e a <strong>Universidade de Vigo</strong> (Post-Growth Innovation Lab), co <strong>IES Luís Seoane</strong> como aliado educativo estratéxico.</p>\n<p>O proxecto propón que as aulas funcionen como espazos de investigación, aprendizaxe crítica, diálogo entre territorios e participación cidadá: <strong>investigar para comprender</strong>, <strong>contrastar o local co global</strong> para interpretar causas, dereitos, desigualdades e interdependencias, e <strong>transformar as aprendizaxes</strong> en capacidade de deliberación, proposta e acción.</p>\n<p>A intervención implica ata 16 centros educativos de Galicia: 10 no itinerario educativo principal e 6 centros rurais vinculados a Postgrowth S.A.:Rural. A V Feira da Sostibilidade é o grande espazo de encontro onde converxen os seus procesos.</p>","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando unha investigación de ciencia cidadá","posicion":"dereita","botons":[{"texto":"As actividades do proxecto","url":"#actividades","estilo":"secundario"}]},{"id":"sod5lx","tipo":"cifras","oculta":false,"fondo":"claro","etiqueta":"SENDA 2030","titulo":"Un proxecto para toda a comunidade educativa.","texto":"Proxecto de Educación para o Desenvolvemento e a Cidadanía Global que mellora a capacidade da comunidade educativa galega para xerar procesos de acción colectiva ante os retos ecosociais, conectando ciencia cidadá, práctica docente, participación xuvenil e cooperación.","cifras":[{"valor":"16","etiqueta":"centros educativos"},{"valor":"350+","etiqueta":"alumnos e alumnas"},{"valor":"30+","etiqueta":"docentes"},{"valor":"10","etiqueta":"microproxectos Eco-Étika"}]},{"id":"spb7yv","tipo":"cronoloxia","oculta":false,"fondo":"branco","etiqueta":"O itinerario","titulo":"Investigar, contrastar, actuar.","fitos":[{"data":"Outono 2026","titulo":"Arranque","texto":"Coordinación cos centros participantes e liña de base.","estado":"agora"},{"data":"Novembro 2026 – marzo 2027","titulo":"Formación, laboratorio e ciencia cidadá","texto":"Formación docente en EpDCG, laboratorio de propostas educativas, obradoiros de cidadanía global e microproxectos Eco-Étika nas aulas.","estado":"proximo"},{"data":"Primavera 2027","titulo":"Diálogo entre territorios","texto":"Encontros local-global con docentes de América Latina, Eco-Étika Conecta e a campaña «Dálle a volta».","estado":"proximo"},{"data":"28–30 abril 2027","titulo":"V Feira da Sostibilidade","texto":"Tres xornadas no IES Luís Seoane co II Foro de Desenvolvemento Local e a I Conferencia COOPEDUGAL.","estado":"proximo"},{"data":"Maio – setembro 2027","titulo":"SENDA Aberta","texto":"Sistematización, documental e guía «Así fixemos SENDA» para que outros centros poidan adaptar a experiencia.","estado":"proximo"}]},{"id":"sqt9z1","tipo":"tarxetas","oculta":false,"fondo":"claro","etiqueta":"Na Feira","titulo":"Que haberá na V Feira.","columnas":2,"items":[{"titulo":"Stands e microproxectos do alumnado","texto":"Os 10 microproxectos Eco-Étika presentados e dinamizados polo alumnado e o profesorado dos centros participantes."},{"titulo":"Investigacións de ciencia cidadá no rural","texto":"Os 6 centros rurais vinculados a Postgrowth S.A.:Rural comparten as súas investigacións sobre a transición ecolóxica xusta."},{"titulo":"II Foro de Desenvolvemento Local","texto":"O rural ante a transición ecolóxica xusta: mesas de deliberación entre alumnado, profesorado e actores do territorio, en colaboración co Concello de Pontevedra."},{"titulo":"I Conferencia COOPEDUGAL","texto":"Dúas xornadas de relatorios, experiencias e o espazo «O Local dende o Sur», vinculadas á Feira."},{"titulo":"Obradoiros, charlas-foro, xogos e escape rooms","texto":"Propostas de centros, entidades sociais, ONGD, universidade e iniciativas do territorio."}]},{"id":"sr718h","tipo":"actividades","oculta":false,"fondo":"branco","ancla":"actividades","etiqueta":"Actividades do proxecto","titulo":"Paso a paso cara á Feira.","texto":"O estado de cada actividade actualízase ao longo do curso.","proxecto":"senda-2030"},{"id":"ss4yv0","tipo":"logos","oculta":false,"fondo":"verde","etiqueta":"Quen participa","titulo":"Centros e entidades.","texto":"Proxecto financiado pola Xunta de Galicia (Cooperación Galega) na convocatoria de proxectos de educación para o desenvolvemento e a cidadanía global 2026 (expediente PR804A-2026-00000029-00).","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega"]},{"titulo":"Colaboran","entidades":["concello-de-pontevedra","cfr-pontevedra"]}]},{"id":"stqkzt","tipo":"lista","oculta":false,"fondo":"verde","titulo":"Centros educativos","items":["IES Luís Seoane (Pontevedra)","Centros participantes en SENDA 2030 das catro provincias","6 centros rurais de Postgrowth S.A.:Rural"]},{"id":"sus5eq","tipo":"noticias","oculta":false,"fondo":"claro","etiqueta":"Actualidade","titulo":"Noticias desta edición.","edicion":"2027","numero":6},{"id":"svuqmo","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres participar nesta edición?","texto":"Centros educativos, entidades, empresas e medios: hai moitas formas de formar parte da Feira.","botons":[{"texto":"Como participar","url":"/participa/","estilo":"principal"}]}]}', 973) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas', 'inicio', '{"seccions":[{"id":"swkfxb","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"#AFeira · IES Luís Seoane · Pontevedra","titulo":"A Feira non son dous días.","destaque":"É un movemento.","texto":"Dende 2023, a Feira da Sostibilidade converte o IES Luís Seoane nun laboratorio aberto onde o alumnado investiga, actúa e constrúe cidadanía crítica xunto a centros educativos, universidade e entidades sociais.","imaxe":"f-multitude-corredor","imaxeAlt":"Corredor do IES Luís Seoane cheo de xente durante a Feira","cifras":[{"valor":"4","etiqueta":"edicións celebradas"},{"valor":"+1.000","etiqueta":"persoas participantes por edición"},{"valor":"30","etiqueta":"entidades colaboradoras na IV edición"},{"valor":"13","etiqueta":"centros de Galicia, España e Europa"}],"botons":[{"texto":"V Feira · 28–30 abril 2027","url":"/edicions/2027/","estilo":"principal"},{"texto":"Que é a Feira","url":"#a-feira","estilo":"secundario"}]},{"id":"sx40zj","tipo":"texto_imaxe","oculta":false,"fondo":"branco","ancla":"a-feira","etiqueta":"A Feira","titulo":"E se un instituto puidese cambiar o mundo?","corpo":"<p>A Feira da Sostibilidade «Pensa, consume e actúa» naceu da iniciativa do colectivo <strong>Eco-Étika</strong>, formado por alumnado do IES Luís Seoane de Pontevedra. O <strong>IES Luís Seoane</strong> organízaa, e <strong>CIDEL Galicia</strong> e o <strong>Post-Growth Innovation Lab da Universidade de Vigo</strong> impúlsana e apóiana.</p><p>O instituto, no barrio de Monte Porreiro, abre as súas portas cada primavera a centros educativos, universidade, entidades sociais, administracións e veciñanza. O alumnado non presenta só resultados: comparte o que investigou, dinamiza actividades e constrúe propostas para o seu territorio.</p>","imaxe":"f-alumnado-presenta-investigacion","imaxeAlt":"Alumnado presentando os resultados dunha investigación cidadá","posicion":"dereita","botons":[{"texto":"Coñece FeiraLab","url":"/feiralab/","estilo":"secundario"}]},{"id":"sy060z","tipo":"edicion_actual","oculta":false,"fondo":"claro","etiqueta":"Próxima edición"},{"id":"szqbsw","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"FeiraLab","titulo":"Máis ca unha feira: un laboratorio.","texto":"Detrás da Feira hai un laboratorio de innovación educativa que traballa todo o curso con tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos.","url":"/feiralab/"},{"etiqueta":"ApS","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina.","url":"/feiralab/"},{"etiqueta":"CC","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global.","url":"/feiralab/"}]},{"id":"s109jns","tipo":"edicions","oculta":false,"fondo":"claro","etiqueta":"As edicións","titulo":"Cada edición suma.","texto":"A Feira é un proceso vivo que medra cada curso: máis centros, máis entidades e máis proxectos do alumnado."},{"id":"s11yce4","tipo":"cita","oculta":false,"fondo":"verde","texto":"O futuro non se explica.","destaque":"Constrúese."},{"id":"s12ll8j","tipo":"noticias","oculta":false,"fondo":"branco","etiqueta":"Actualidade","titulo":"O proceso en directo.","numero":3},{"id":"s130zmn","tipo":"galeria","oculta":false,"fondo":"claro","etiqueta":"IV Feira da Sostibilidade","titulo":"Así foi a última Feira.","imaxes":[{"imaxe":"f-stand-2","alt":"Stand número 2 da Feira con materiais do alumnado"},{"imaxe":"f-stand-alumnas","alt":"Alumnas explicando o seu stand a outras visitantes"},{"imaxe":"f-xogo-inclusivo","alt":"Nenas e nenos xogando a un xogo inclusivo no chan"},{"imaxe":"f-stand-4-ruleta","alt":"Stand con ruleta de xogo e voluntariado atendendo"},{"imaxe":"f-exposicion-carteis","alt":"Exposición de carteis no corredor"},{"imaxe":"f-stand-15","alt":"Posto 15 do alumnado con produtos de deseño propio"},{"imaxe":"f-obradoiro-mans","alt":"Mans traballando nun obradoiro"},{"imaxe":"f-charla-auditorio","alt":"Charla no salón de actos ante o alumnado"}]},{"id":"s14zlbv","tipo":"logos","oculta":false,"fondo":"branco","etiqueta":"O ecosistema","titulo":"Unha rede que multiplica o impacto.","texto":"Entidades sociais, ONGD, cooperativas, administracións e iniciativas do territorio que fan a Feira posible.","grupos":[{"titulo":"Colaboran","entidades":["oxfam-intermon","adega","cogami","solidariedade-internacional","afectados-a57","ec4rural","cruz-vermella","feitoria-verde","galicia-ambiental","sig-comercio-xusto","casa-grande-de-xanceda","o-colmenar-de-sara"]}]},{"id":"s15jjlc","tipo":"chamada","oculta":false,"fondo":"morado","etiqueta":"Participa","titulo":"Non veñas só mirar. Participa.","texto":"Centros educativos, entidades, empresas e medios: hai moitas formas de formar parte da Feira.","botons":[{"texto":"Como participar","url":"/participa/","estilo":"principal"},{"texto":"@feiradasostibilidade","url":"https://www.instagram.com/feiradasostibilidade","estilo":"secundario"}]}]}', 0) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'feiralab', '{"titulo":"FeiraLab","descricion":"A Feira da Sostibilidade como laboratorio de innovación educativa: investigación, acción e cidadanía crítica durante todo o curso.","nai":"","imaxe":"f-stand-alumnas","seccions":[{"id":"s16vdl8","tipo":"heroe","oculta":false,"fondo":"claro","etiqueta":"FeiraLab · Xeración Eco-Étika","titulo":"Máis ca unha feira.","destaque":"Un laboratorio permanente.","texto":"A Feira é o momento no que meses de investigación, acción e construción colectiva de cidadanía crítica se fan visibles para toda a comunidade. Detrás hai un laboratorio de innovación educativa que traballa durante todo o curso.","imaxe":"f-stand-alumnas","imaxeAlt":"Alumnas explicando o seu stand na Feira"},{"id":"s173bbe","tipo":"tarxetas","oculta":false,"fondo":"verde","etiqueta":"Como traballamos","titulo":"Tres metodoloxías que se retroalimentan.","columnas":3,"items":[{"etiqueta":"ABP · Aprendizaxe Baseada en Proxectos","titulo":"Investigar para comprender","texto":"O alumnado deseña e executa proxectos de investigación interdisciplinar sobre retos da Axenda 2030, conectando saberes científicos, sociais e artísticos."},{"etiqueta":"ApS · Aprendizaxe Servizo · CIDEL Galicia","titulo":"Actuar para transformar","texto":"O eixo que une aprendizaxe e acción comunitaria: o alumnado pon o seu coñecemento ao servizo da comunidade, con rede internacional con colectivos de Galicia e América Latina."},{"etiqueta":"CC · Ciencia cidadá · Post-Growth Innovation Lab","titulo":"Investigar con rigor e impacto real","texto":"Co acompañamento científico da Universidade de Vigo, o alumnado convértese en investigador activo e conecta o local —o barrio de Monte Porreiro— co global."}]},{"id":"s182bpq","tipo":"tarxetas","oculta":false,"fondo":"branco","etiqueta":"Liñas de traballo","titulo":"Proxectos que moven o mundo.","texto":"O alumnado investiga en liñas temáticas conectadas cos ODS que se desenvolven ao longo do curso e culminan na Feira.","columnas":3,"items":[{"etiqueta":"ODS 7 · ODS 13","titulo":"Clima, enerxía e transición ecolóxica","texto":"Cambio climático, consumo enerxético e transición xusta: datos reais, alternativas e comunicación á comunidade."},{"etiqueta":"ODS 12","titulo":"Consumo responsable e moda sostible","texto":"O impacto da fast fashion e do consumismo, xogos educativos como Naturpoly e obradoiros de economía circular."},{"etiqueta":"ODS 10 · ODS 16","titulo":"Xustiza global e cooperación internacional","texto":"Dereitos humanos, desigualdade e solidariedade internacional, en colaboración con Oxfam Intermón e SIG Comercio Xusto."},{"etiqueta":"ODS 5","titulo":"Igualdade de xénero e diversidade","texto":"Investigación e acción sobre fendas de xénero, diversidade e inclusión, co proxecto NeoFem e o Comité UNESCO do centro."},{"etiqueta":"ODS 11","titulo":"Territorio, barrio e identidade local","texto":"Monte Porreiro como laboratorio social: mapeo comunitario e axendas políticas locais."},{"etiqueta":"ODS 2 · ODS 3","titulo":"Saúde, benestar e alimentación sostible","texto":"Alimentación ecolóxica, hortas escolares, saúde mental e benestar, con entidades como Casa Grande de Xanceda e Feitoria Verde."}]},{"id":"s19qkpm","tipo":"cronoloxia","oculta":false,"fondo":"escuro","etiqueta":"Recoñecementos","titulo":"Premios autonómicos de innovación educativa.","fitos":[{"data":"2022 · 2023","titulo":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)","estado":"feito"},{"data":"2024","titulo":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane","estado":"feito"}]},{"id":"s1an2cy","tipo":"subpaxinas","oculta":false,"fondo":"claro","etiqueta":"No laboratorio","titulo":"Máis sobre FeiraLab.","nai":"feiralab"},{"id":"s1b7lku","tipo":"chamada","oculta":false,"fondo":"morado","titulo":"Queres traer o laboratorio ao teu centro?","texto":"Escríbenos e contamos como participar na próxima Feira.","botons":[{"texto":"Participa","url":"/participa/","estilo":"principal"}]}]}', 1) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('paxinas_libres', 'aviso-legal', '{"titulo":"Aviso legal","nai":"","borrador":false,"seccions":[{"id":"s1cf1gs","tipo":"texto","oculta":false,"fondo":"branco","corpo":"<h2>Titularidade</h2><p>Esta web divulga a Feira da Sostibilidade do IES Luís Seoane (Pontevedra) e os proxectos educativos vinculados. Organiza o IES Luís Seoane, e impulsan CIDEL Galicia e a Universidade de Vigo.</p><h2>Privacidade</h2><p>Esta web non usa cookies de seguimento. Os datos que envías a través dos formularios de Participa só se usan para organizar a túa participación na Feira, non se ceden a terceiros e elimínanse cando deixan de ser necesarios. Podes pedir que se consulten, corrixan ou eliminen escribindo ás entidades organizadoras.</p><p>As tipografías cárganse desde Google Fonts. As ligazóns a servizos externos (Instagram, plataformas de vídeo) réxense polas políticas desas plataformas.</p><h2>Imaxes de menores</h2><p>As imaxes nas que aparece alumnado publícanse coa autorización correspondente dos centros educativos. Se apareces nunha imaxe e queres que se retire, contacta co IES Luís Seoane e retirarémola.</p><h2>Licenza dos contidos</h2><p>Salvo indicación contraria, os textos e recursos desta web publícanse baixo licenza <a href=\"https://creativecommons.org/licenses/by-sa/4.0/deed.gl\">Creative Commons Recoñecemento-CompartirIgual 4.0 (CC BY-SA 4.0)</a>. Os logotipos pertencen ás súas respectivas entidades.</p>"}]}', 90) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
INSERT INTO documentos (coleccion, id, datos, orde) VALUES ('axustes', 'xeral', '{"nome":"Feira da Sostibilidade","lema":"Pensa, consume e actúa","descricion":"A Feira da Sostibilidade do IES Luís Seoane (Pontevedra): un movemento educativo de alumnado, profesorado, universidade e entidades sociais arredor dos retos ecosociais e da cidadanía global.","edicionActual":"2027","instagram":"https://www.instagram.com/feiradasostibilidade","instagramUsuario":"@feiradasostibilidade","webIes":"https://iesluisseoane.org/","pe":{"texto":"Pensa, consume e actúa. Un movemento educativo nacido no IES Luís Seoane de Pontevedra a partir do colectivo Eco-Étika.","grupos":[{"titulo":"Organiza","entidades":["ies-luis-seoane"]},{"titulo":"Impulsan","entidades":["cidel-galicia","universidade-de-vigo"]},{"titulo":"Co apoio de","entidades":["cooperacion-galega"],"nota":"V Feira · proxecto SENDA 2030"}],"premios":[{"ano":"2022 · 2023","texto":"Premio Galicons-net de Innovación Educativa en Consumo Responsable (Xunta de Galicia)"},{"ano":"2024","texto":"III Premio Galego de Educación para o Desenvolvemento e a Cidadanía Global, á experiencia de Eco-Étika e o IES Luís Seoane"}]}}', 0) ON CONFLICT(coleccion, id) DO UPDATE SET datos = excluded.datos, actualizado = datetime('now');
